/* ===========================================================================
 * 20) BANDEAU « PAIEMENT EN LIGNE OU APRÈS LIVRAISON »
 *     ------------------------------------------------------------------
 *     Beaucoup de visiteurs renoncent a commander en croyant qu il faut
 *     payer par carte immediatement. Ce bandeau leve le doute aux trois
 *     endroits ou la question se pose :
 *       - la boutique, avant meme le choix des produits ;
 *       - le panier, au moment de se decider ;
 *       - la page de commande, juste au-dessus du choix du moyen de paiement.
 *
 *     >>> PREREQUIS COTE WOOCOMMERCE <<<
 *     Ce bandeau annonce une possibilite : encore faut-il que le moyen de
 *     paiement correspondant soit actif. Verifiez dans
 *     WooCommerce > Reglages > Paiements que « Paiement a la livraison »
 *     (parfois nomme « Paiement a la remise ») est bien active. Sinon le
 *     client lira le message sans trouver l option, ce qui serait pire que
 *     de ne rien annoncer.
 * =========================================================================== */

/** Le texte du bandeau, defini une seule fois. */
function eauservice_bandeau_paiement() {
	$html  = '<aside class="es-pay" aria-label="Moyens de paiement">';
	$html .= '<div class="es-pay-ico">&#128179;</div>';
	$html .= '<div class="es-pay-txt">';
	$html .= '<strong class="es-pay-t">Payez en ligne ou après la livraison, c\'est vous qui choisissez</strong>';
	$html .= '<span class="es-pay-d">Réglez par carte bancaire au moment de la commande, ou <strong>après la livraison et l\'installation</strong> de votre matériel. Le choix se fait à l\'étape du paiement. Entreprises, collectivités et agences&nbsp;: règlement par virement sur facture également possible.</span>';
	$html .= '</div></aside>';
	return $html;
}

// 20a. Sur la boutique, juste sous les blocs de reassurance.
add_action( 'woocommerce_before_shop_loop', 'eauservice_pay_boutique', 8 );
function eauservice_pay_boutique() {
	if ( ! ( function_exists( 'is_shop' ) && is_shop() ) ) { return; }
	if ( function_exists( 'is_paged' ) && is_paged() ) { return; }
	echo eauservice_bandeau_paiement();
}

// 20b. Sur la fiche produit, sous le bouton d ajout au panier.
add_action( 'woocommerce_after_add_to_cart_form', 'eauservice_pay_produit', 20 );
function eauservice_pay_produit() {
	echo eauservice_bandeau_paiement();
}

// 20c. En haut du panier.
add_action( 'woocommerce_before_cart', 'eauservice_pay_panier', 8 );
function eauservice_pay_panier() {
	echo eauservice_bandeau_paiement();
}

// 20d. Sur la page de commande, juste avant le choix du moyen de paiement.
//      C est l endroit le plus utile : le client y prend sa decision.
add_action( 'woocommerce_review_order_before_payment', 'eauservice_pay_commande', 5 );
function eauservice_pay_commande() {
	echo eauservice_bandeau_paiement();
}


/* ===========================================================================
 * 21) COMPATIBILITÉ RANK MATH — NE JAMAIS PUBLIER DEUX FOIS LA MÊME CHOSE
 *     ------------------------------------------------------------------
 *     Rank Math publie deja, de lui-meme, les schemas Organization,
 *     LocalBusiness, WebPage, BreadcrumbList et FAQPage. Si ce snippet en
 *     publiait aussi, Google recevrait deux fiches concurrentes pour la meme
 *     entreprise et ne saurait pas laquelle fait foi : c est exactement le
 *     probleme que nous venons de supprimer sur la page d accueil.
 *
 *     La regle appliquee ici est donc simple :
 *       - Rank Math reste le SEUL a decrire l entreprise et la navigation ;
 *       - ce snippet se contente d AJOUTER a la fiche de Rank Math ce qu elle
 *         ne contient pas : moyens de paiement, villes desservies, et le lien
 *         vers Events Café.
 *
 *     Les schemas Service (section 9c) et FAQ de la boutique (section 10) sont
 *     conserves : Rank Math ne les genere pas pour ces contenus, qui sont du
 *     HTML sur mesure. Il n y a donc pas de doublon.
 *
 *     >>> SI VOUS DESINSTALLEZ RANK MATH <<<
 *     Rien a faire : ce snippet detecte son absence et reprend automatiquement
 *     la publication de la fiche etablissement.
 * =========================================================================== */

/** Rank Math est-il actif ? */
function eauservice_rank_math_actif() {
	// Permet de forcer nos propres schemas si besoin, en definissant
	// EAUSERVICE_IGNORER_RANK_MATH a true.
	if ( defined( 'EAUSERVICE_IGNORER_RANK_MATH' ) && EAUSERVICE_IGNORER_RANK_MATH ) {
		return false;
	}
	return defined( 'RANK_MATH_VERSION' )
		|| class_exists( 'RankMath\Helper' )
		|| function_exists( 'rank_math' );
}

